import fs from 'fs';
import {Client} from '@modelcontextprotocol/sdk/client/index.js';
import {StreamableHTTPClientTransport} from '@modelcontextprotocol/sdk/client/streamableHttp.js';
const D=process.env.D4;
const tok=JSON.parse(fs.readFileSync(D+'/maria-token.json','utf8')).token;
const [name,args]=[process.argv[2],JSON.parse(process.argv[3]||'{}')];
const c=new Client({name:'maria-agent',version:'1'});
await c.connect(new StreamableHTTPClientTransport(new URL('http://localhost:8810/mcp'),{requestInit:{headers:{Authorization:'Bearer '+tok}}}));
const t0=Date.now();
const r=await c.callTool({name,arguments:args});
const out=r.content.map(x=>x.type==='text'?x.text:'['+x.type+']').join('\n');
console.log((r.isError?'ERROR ':'')+out.slice(0,+process.env.MAX||6000));
console.error('ms',Date.now()-t0);
await c.close();
EOF
